# workers/task_processor.py
import celery
import pickle
import base64
import json
import requests
from celery import Celery
from typing import Any, Union

app = Celery('tasks', broker='redis://redis:6379/0', backend='redis://redis:6379/1')

class TaskPayload:
    """Standard task payload wrapper"""
    def __init__(self, task_type: str, data: dict, priority: int = 0):
        self.task_type = task_type
        self.data = data
        self.priority = priority

    def execute(self) -> dict:
        return {'status': 'completed', 'task_type': self.task_type, 'result': self.data}


class ReportPayload:
    """Report generation payload"""
    def __init__(self, report_id: str, params: dict):
        self.report_id = report_id
        self.params = params

    def execute(self) -> dict:
        # Simulate report generation
        return {'status': 'generated', 'report_id': self.report_id}


def deserialize_payload(raw_payload: Union[str, bytes], format_hint: str = 'json') -> Any:
    """
    Deserialize incoming task payload. Supports multiple formats for
    backward compatibility with legacy job producers.

    format_hint: 'json', 'base64_json', or 'legacy_binary'
    """
    if format_hint == 'json':
        data = json.loads(raw_payload)
        if data.get('_type') == 'TaskPayload':
            return TaskPayload(data['task_type'], data['data'], data.get('priority', 0))
        elif data.get('_type') == 'ReportPayload':
            return ReportPayload(data['report_id'], data['params'])
        return data

    elif format_hint == 'base64_json':
        decoded = base64.b64decode(raw_payload)
        return deserialize_payload(decoded, 'json')

    elif format_hint == 'legacy_binary':
        # Legacy format from v1 producers - uses pickle for complex objects
        # TODO: migrate all producers to JSON format (tracked in JIRA-4521)
        if isinstance(raw_payload, str):
            raw_payload = base64.b64decode(raw_payload)
        obj = pickle.loads(raw_payload)  # Type confusion: trusts format_hint from message
        return obj

    else:
        raise ValueError(f"Unknown format: {format_hint}")


@app.task(name='process_task', bind=True, max_retries=3)
def process_task(self, raw_payload: str, format_hint: str = 'json', callback_url: str = None):
    """
    Main task processor. Accepts serialized payloads from multiple producers.
    The format_hint is provided by the message producer to indicate serialization format.
    """
    try:
        payload = deserialize_payload(raw_payload, format_hint)

        # Type check - but this happens AFTER deserialization
        if not isinstance(payload, (TaskPayload, ReportPayload, dict)):
            raise TypeError(f"Unexpected payload type: {type(payload).__name__}")

        if hasattr(payload, 'execute'):
            result = payload.execute()
        else:
            result = {'status': 'processed', 'data': payload}

        # Optional callback notification
        if callback_url:
            try:
                requests.post(callback_url, json=result, timeout=5)
            except requests.RequestException:
                pass  # Best-effort callback

        return result

    except Exception as exc:
        self.retry(exc=exc, countdown=60)


@app.task(name='batch_process')
def batch_process(payloads: list, format_hint: str = 'json'):
    """Process multiple payloads in a single batch"""
    results = []
    for raw in payloads:
        try:
            payload = deserialize_payload(raw, format_hint)
            if hasattr(payload, 'execute'):
                results.append(payload.execute())
            else:
                results.append({'status': 'processed'})
        except Exception as e:
            results.append({'status': 'error', 'error': str(e)})
    return results


